class _MaterialTaminotchiHistoryScreenState
    extends State<MaterialTaminotchiHistoryScreen> {
  late Future<List<AdminRawMaterialEvent>> _historyFuture;
  List<AdminApparatus> _apparatusCatalog = const [];

  @override
  void initState() {
    super.initState();
    _historyFuture = _loadHistory();
    unawaited(_loadApparatusCatalog());
  }

  Future<void> _loadApparatusCatalog() async {
    try {
      final apparatus = await MobileApi.instance.adminApparatus(limit: 10000);
      if (!mounted) return;
      setState(() => _apparatusCatalog = apparatus);
    } catch (_) {
      // The exact ApparatusId remains visible if display projection fails.
    }
  }

  Future<List<AdminRawMaterialEvent>> _loadHistory() {
    return MobileApi.instance.adminRawMaterialHistory(limit: 100);
  }

  Future<void> _refresh() async {
    final future = _loadHistory();
    setState(() {
      _historyFuture = future;
    });
    await future;
  }

  void _openDrawerRoute(String route) {
    final current = ModalRoute.of(context)?.settings.name;
    if (current == route) {
      return;
    }
    Navigator.of(context).pushReplacementNamed(route);
  }

  void _goBack() {
    final nav = Navigator.of(context);
    if (nav.canPop()) {
      nav.pop();
      return;
    }
    nav.pushReplacementNamed(AppRoutes.materialHome);
  }

  Future<void> _showHistoryDetails(AdminRawMaterialEvent event) async {
    await showModalBottomSheet<void>(
      context: context,
      useSafeArea: true,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      barrierColor: Colors.black.withValues(alpha: 0.32),
      builder: (sheetContext) => _MaterialHistoryDetailsSheet(
        event: event,
        apparatusCatalog: _apparatusCatalog,
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final bottomPadding = MediaQuery.viewPaddingOf(context).bottom + 136.0;
    return AppShell(
      leading: IconButton(
        icon: const Icon(Icons.arrow_back_rounded),
        onPressed: _goBack,
      ),
      title: 'Harakatlar tarixi',
      subtitle: '',
      nativeTopBar: true,
      nativeTitleTextStyle: AppTheme.werkaNativeAppBarTitleStyle(context),
      drawer: MaterialTaminotchiNavigationDrawer(
        selectedRouteName: AppRoutes.materialHistory,
        onNavigate: _openDrawerRoute,
      ),
      preferNativeTitle: true,
      contentPadding: EdgeInsets.zero,
      bottom: const MaterialTaminotchiDock(
        activeTab: MaterialTaminotchiDockTab.home,
      ),
      child: AppRefreshIndicator(
        onRefresh: _refresh,
        allowRefreshOnShortContent: true,
        child: ListView(
          physics: const TopRefreshScrollPhysics(),
          padding: EdgeInsets.fromLTRB(0, 8, 0, bottomPadding),
          children: [
            _MaterialHistoryPanel(
              future: _historyFuture,
              apparatusCatalog: _apparatusCatalog,
              maxItems: 100,
              onEventTap: (event) => _showHistoryDetails(event),
              onRetry: () {
                setState(() {
                  _historyFuture = _loadHistory();
                });
              },
            ),
          ],
        ),
      ),
    );
  }
}

class MaterialTaminotchiHomeScreen extends StatefulWidget {
  const MaterialTaminotchiHomeScreen({super.key});

  @override
  State<MaterialTaminotchiHomeScreen> createState() =>
      _MaterialTaminotchiHomeScreenState();
}

class _MaterialTaminotchiHomeScreenState
    extends State<MaterialTaminotchiHomeScreen> {
  bool _materialFabOpen = false;

  Future<void> _refreshProfile() async {
    try {
      await MobileApi.instance.profile();
      if (mounted) {
        setState(() {});
      }
    } catch (_) {
      if (mounted) {
        setState(() {});
      }
    }
  }

  void _openDrawerRoute(String route) {
    final current = ModalRoute.of(context)?.settings.name;
    if (current == route) {
      return;
    }
    Navigator.of(context).pushReplacementNamed(route);
  }

  void _openRoute(String route) {
    if (route == AppRoutes.profile || route == AppRoutes.gscaleMode) {
      Navigator.of(context).pushNamed(route);
      return;
    }
    Navigator.of(context).pushNamed(route);
  }

  void _setMaterialFabOpen(bool open) {
    if (!mounted || _materialFabOpen == open) {
      return;
    }
    setState(() => _materialFabOpen = open);
  }

  List<AdminFabMenuAction> _materialFabActions(
    bool hasMaterialGroupScope,
  ) {
    final actions = <AdminFabMenuAction>[];
    if (AppRouter.canOpenRoute(AppRoutes.gscaleMode)) {
      actions.add(
        AdminFabMenuAction(
          title: 'Kirim',
          icon: Icons.scale_outlined,
          onTap: () {
            _setMaterialFabOpen(false);
            _openRoute(AppRoutes.gscaleMode);
          },
        ),
      );
    }
    if (AppRouter.canOpenRoute(AppRoutes.adminRawMaterialAssignments)) {
      actions.add(
        AdminFabMenuAction(
          title: 'QR skanerlash',
          icon: Icons.qr_code_scanner_rounded,
          onTap: () {
            _setMaterialFabOpen(false);
            unawaited(_scanRawMaterial(hasMaterialGroupScope));
          },
        ),
      );
      actions.add(
        AdminFabMenuAction(
          title: 'Homashyo biriktirish',
          icon: Icons.inventory_2_outlined,
          onTap: () {
            _setMaterialFabOpen(false);
            if (!hasMaterialGroupScope) {
              ScaffoldMessenger.of(context).showSnackBar(
                const SnackBar(
                  content:
                      Text('Avval material guruhlari biriktirilishi kerak'),
                ),
              );
              return;
            }
            _openRoute(AppRoutes.adminRawMaterialAssignments);
          },
        ),
      );
    }
    if (AppRouter.canOpenRoute(AppRoutes.inventoryMovements)) {
      actions.add(
        AdminFabMenuAction(
          title: 'Joylashtirish va transfer',
          icon: Icons.swap_horiz_rounded,
          onTap: () {
            _setMaterialFabOpen(false);
            _openRoute(AppRoutes.inventoryMovements);
          },
        ),
      );
    }
    return actions;
  }

  Future<void> _scanRawMaterial(bool hasMaterialGroupScope) async {
    if (!hasMaterialGroupScope) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Avval material guruhlari biriktirilishi kerak'),
        ),
      );
      return;
    }
    final barcode = await showRawMaterialScanDialog(context);
    if (!mounted || barcode == null || barcode.trim().isEmpty) {
      return;
    }
    Navigator.of(context).pushNamed(
      AppRoutes.adminRawMaterialAssignments,
      arguments: AdminRawMaterialAssignmentArgs(
        initialBarcode: rawMaterialBarcodeFromQr(barcode),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final profile = AppSession.instance.profile;
    final groups = profile?.assignedItemGroups ?? const <String>[];
    final hasMaterialGroupScope = groups.isNotEmpty;
    final bottomPadding = MediaQuery.viewPaddingOf(context).bottom + 136.0;
    final fabActions = _materialFabActions(hasMaterialGroupScope);

    return AppShell(
      title: 'Material ta’minotchisi',
      subtitle: '',
      nativeTopBar: true,
      nativeTitleTextStyle: AppTheme.werkaNativeAppBarTitleStyle(context),
      drawer: MaterialTaminotchiNavigationDrawer(
        selectedRouteName: AppRoutes.materialHome,
        onNavigate: _openDrawerRoute,
      ),
      preferNativeTitle: true,
      contentPadding: EdgeInsets.zero,
      bottom: const MaterialTaminotchiDock(
        activeTab: MaterialTaminotchiDockTab.home,
      ),
      child: Stack(
        children: [
          AppRefreshIndicator(
            onRefresh: _refreshProfile,
            allowRefreshOnShortContent: true,
            child: ListView(
              physics: const TopRefreshScrollPhysics(),
              padding: EdgeInsets.fromLTRB(0, 8, 0, bottomPadding),
              children: [
                if (!hasMaterialGroupScope) ...[
                  const SmoothAppear(
                    delay: Duration(milliseconds: 20),
                    child: _MaterialScopeNotice(),
                  ),
                  const SizedBox(height: 14),
                ],
                SmoothAppear(
                  delay: const Duration(milliseconds: 40),
                  child: _MaterialActionPanel(
                    hasMaterialGroupScope: hasMaterialGroupScope,
                    onOpenRoute: _openRoute,
                  ),
                ),
              ],
            ),
          ),
          if (fabActions.isNotEmpty)
            PositionedDirectional(
              end: 16,
              bottom: 16,
              child: AdminFabActionMenu(
                key: const ValueKey('material-raw-material-scan-fab'),
                open: _materialFabOpen,
                actions: fabActions,
                onToggle: () => _setMaterialFabOpen(!_materialFabOpen),
                closedLabel: 'Amallar',
                openLabel: 'Yopish',
                closedIcon: Icons.add_rounded,
                openIcon: Icons.close_rounded,
              ),
            ),
        ],
      ),
    );
  }
}

class _MaterialHistoryPanel extends StatelessWidget {
  const _MaterialHistoryPanel({
    required this.future,
    required this.apparatusCatalog,
    required this.onRetry,
    required this.onEventTap,
    this.maxItems = 6,
  });

  final Future<List<AdminRawMaterialEvent>> future;
  final List<AdminApparatus> apparatusCatalog;
  final VoidCallback onRetry;
  final ValueChanged<AdminRawMaterialEvent> onEventTap;
  final int maxItems;

  @override
  Widget build(BuildContext context) {
    return Padding(
      padding: const EdgeInsets.symmetric(horizontal: 4),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          FutureBuilder<List<AdminRawMaterialEvent>>(
            future: future,
            builder: (context, snapshot) {
              if (snapshot.connectionState == ConnectionState.waiting) {
                return const _MaterialHistoryLoading();
              }
              if (snapshot.hasError) {
                final message = _materialHistoryErrorMessage(snapshot.error);
                return _MaterialHistoryMessage(
                  icon: Icons.error_outline_rounded,
                  title: 'Tarix yuklanmadi',
                  subtitle: message,
                  onTap: onRetry,
                );
              }
              final events = snapshot.data ?? const <AdminRawMaterialEvent>[];
              if (events.isEmpty) {
                return const _MaterialHistoryMessage(
                  icon: Icons.history_toggle_off_rounded,
                  title: 'Harakatlar hali yo‘q',
                );
              }
              final visible = events.take(maxItems).toList(growable: false);
              return M3SegmentSpacedColumn(
                padding: EdgeInsets.zero,
                children: [
                  for (var i = 0; i < visible.length; i++)
                    _MaterialHistoryCard(
                      slot: M3SegmentedListGeometry.standaloneListSlotForIndex(
                        i,
                        visible.length,
                      ),
                      event: visible[i],
                      apparatusCatalog: apparatusCatalog,
                      onTap: () => onEventTap(visible[i]),
                    ),
                ],
              );
            },
          ),
        ],
      ),
    );
  }
}

